You are an expert in hardware formal verification. You run a property-directed simplification flow on a Yosys-flattened design, step by step. Tools check every step: you only (1) split the property into cases and (2) choose abstraction operators. You never rewrite the RTL.

## Design (SystemVerilog, top module main)
// Model to check the equivalence of two different FIFO implementations.
// This example is taken from Ken McMillan's "A Conjunctively Decomposed
// Boolean Representation for Symbolic Model Checking" (CAV'96), though
// the details are probably different.
//
// Author: Fabio Somenzi <Fabio@Colorado.EDU>

module main(rst, clk,dataIn,push,pop,equal);
    parameter	   MSBD = 3;
    parameter	   LAST = 15;
    parameter	   MSBA = 3;
    input	   clk;
    input      rst;
    input [MSBD:0] dataIn;
    input	   push;
    input	   pop;
    output	   equal;

    wire [MSBD:0]  srDataOut;
    wire	   srFull, srEmpty;
    wire [MSBD:0]  rbDataOut;
    wire	   rbFull, rbEmpty;

    //srFIFO #(MSBD,LAST,MSBA) sr (clk, dataIn, push, pop,
		//		srDataOut, srFull, srEmpty);

    srFIFO sr (rst, clk, dataIn, push, pop,
				srDataOut, srFull, srEmpty);
    rbFIFO rb (rst, clk, dataIn, push, pop,
				rbDataOut, rbFull, rbEmpty);

    //rbFIFO #(MSBD,LAST,MSBA) rb (clk, dataIn, push, pop,
		//	rbDataOut, rbFull, rbEmpty);
    // The outputs of the two FIFOs are not specified when the
    // buffers are empty.
    assign equal = (srFull == rbFull) & (srEmpty == rbEmpty) &
	(srEmpty | (srDataOut == rbDataOut));

    property prop;
        @(posedge clk) disable iff (rst) (equal == 1); 
    endproperty

endmodule // compareFIFOs


// Shift register FIFO.
// tail points to the first element of the queue unless the buffer is empty.
// the new data is always inserted in position 0 of the buffer, after
// shifting the contents up by one position.
// A push on a full buffer is a NOOP.
// A pop from an empty buffer is a NOOP.
// If both push and pop are asserted at the same clk cycle, only the push
// operation is performed.
// dataOut gives the first element of the queue unless the buffer is empty,
// in which case its value is arbitrary.
module srFIFO(rst,clk,dataIn,push,pop,dataOut,full,empty);
    parameter	    MSBD = 3;
    parameter	    LAST = 15;
    parameter	    MSBA = 3;
    input	    clk;
    input       rst;
    input [MSBD:0]  dataIn;
    input	    push;
    input	    pop;
    output [MSBD:0] dataOut;
    output	    full;
    output	    empty;

    reg [MSBD:0]    mem[0:LAST];
    reg [MSBA:0]    tail;
    reg		    empty;
    integer	    i;

    task initialize_srFIFO; begin
	for (i = 0; i <= LAST; i = i + 1)
	    mem[i] = 0;
	tail = 0;
	empty = 1;
    end
    endtask

    always @ (posedge clk) begin
    if (rst) initialize_srFIFO;
    else begin
	if (push & ~full) begin
	    for (i = LAST; i > 0; i = i - 1)
		mem[i] = mem[i - 1];
	    mem[0] = dataIn;
	    if (~empty)
		tail = tail + 1;
	    empty = 0;
	end // if (push & ~full)
	else if (pop & ~empty) begin
	    if (tail == 0)
		empty = 1;
	    else
		tail = tail - 1;
	end // if (pop & ~empty)
    end // ~rst
    end // always @ (posedge clk)

    assign dataOut = mem[tail];

    assign full = tail == LAST;

endmodule // srFIFO


// Ring buffer FIFO.
// head points to the insertion point unless the buffer is full.
// tail points to the first element in the queue unless the buffer is empty.
// A push on a full buffer is a NOOP.
// A pop from an empty buffer is a NOOP.
// If both push and pop are asserted at the same clk cycle, only the push
// operation is performed.
// dataOut gives the first element of the queue unless the buffer is empty,
// in which case its value is arbitrary. 
module rbFIFO(rst, clk,dataIn,push,pop,dataOut,full,empty);
    parameter	    MSBD = 3;
    parameter	    LAST = 15;
    parameter	    MSBA = 3;
    input	    clk;
    input       rst;
    input [MSBD:0]  dataIn;
    input	    push;
    input	    pop;
    output [MSBD:0] dataOut;
    output	    full;
    output	    empty;

    reg [MSBD:0]    mem[0:LAST];
    reg [MSBA:0]    head;   
    reg [MSBA:0]    tail;
    reg		    empty;
    integer	    i;

    task initialize_rbFIFO; begin
	for (i = 0; i <= LAST; i = i + 1)
	    mem[i] = 0;
	head = 0;
	tail = 0;
	empty = 1;
    end //
    endtask

    always @ (posedge clk) begin
    if (rst) initialize_rbFIFO;
    else begin
	if (push & ~full) begin
	    mem[head] = dataIn;
	    head = head + 1;
	    empty = 0;
	end // if (push & ~full)
	else if (pop & ~empty) begin
	    tail = tail + 1;
	    if (tail == head)
		empty = 1;
	end // if (pop & ~empty)
    end // ~rst
    end // always @ (posedge clk)

    assign dataOut = mem[tail];

    assign full = (tail == head) & ~empty;

endmodule // rbFIFO


## Property
The model has one assertion, checked in every cycle: if rst is low then equal == 1 ("assert (!rst -> equal)").
The model is the flattened netlist; there is one assumption: rst is high in the first cycle. The assertion is also available as two 1-bit signals: prop_en (the assertion is enforced while it is high) and prop_a (the asserted value).

## Signals
Signals are named by the identifiers listed in each request (the flattened Yosys wire name with every non-alphanumeric character replaced by '_', for example sr.tail is sr_tail and sr.mem[3] is sr_mem_3). Use only these identifiers.

## Split
A split is a list of cases, each a Verilog boolean expression over signal identifiers (evaluated in every cycle, on the current values of states, inputs and wires). Piece i checks: case_i -> (~prop_en | prop_a) in every cycle. The split is accepted only if a SAT check shows that the OR of the cases is true for ALL values of the signals (it covers every situation, reachable or not). When a piece is split again, its new cases are intersected with the piece's own case and must cover it.
Split on the source of hardness, not on output conditions: a proof over all indices or all slots stays whole under a split on outputs (full, empty, flags), but fixing the index register or pointer it quantifies over instantiates it. Two ways to give a split:
- {"cases":[{"id":"c0","condition":"<verilog expression>"}, ...]}: explicit cases (at most 16 per piece).
- {"index":ID,"bits":n,"auto":true|false}: the tool splits register ID on its n highest bits not yet fixed in this piece (2^n cases, top bit first). With "auto":true, children that time out are split on the next bit by the tool, without asking you again. Use this for an index or pointer register.
Pieces already proved are never touched again.

## Abstraction operators (class A: every one only adds behaviours, so UNSAT on the abstract model is a real proof)
- {"op":"abstract_value","target":ID,"enable":ID|null,"enablen":ID|null,"slice":"hi:lo"|"i"|null}: replace the driver of wire ID by a free value (same as cutpoint). enable/enablen: free only while the 1-bit signal is high/low.
- {"op":"abstract_state","target":ID,"enable":...,"enablen":...,"slice":...,"initstates":N|null}: register ID loads a free value every clock edge (while enable holds / in the first N cycles). Memory words are registers sr_mem_0 .. rb_mem_15, so this also covers memory havoc.
- {"op":"abstract_init","target":ID,"slice":...}: register ID gets a free initial value.
- {"op":"drop_assume"}: remove the assumption (rst is high in the first cycle).
Not available (reject if you use them): any other operator, rewriting expressions, new assumptions or lemmas, cutpoint -blackbox (the design is flat), UF pairing. (The two FIFOs do not compute the same functions.)

## Verdicts
rIC3 (portfolio of IC3/BMC/k-induction) returns UNSAT (piece proved), SAT (counterexample; replayed on the concrete model: real if it reproduces, spurious otherwise) or TIMEOUT. The cap per piece is short (3 s at first, longer in later rounds), so a timeout means "not easy yet", not "impossible". Prefer fewer free values: when refining, prefer enable or slice over restoring a whole signal.

## Answer format
Answer with one JSON object and nothing else (no markdown fence). The shape is given in each request.

